  'techniques.fourSevenEight.detail': '\u0391\u03bd\u03b1\u03c0\u03c4\u03cd\u03c7\u03b8\u03b7\u03ba\u03b5 \u03b1\u03c0\u03cc \u03c4\u03bf\u03bd \u0394\u03c1. Andrew Weil. \u0397 \u03c0\u03b1\u03c1\u03b1\u03c4\u03b5\u03c4\u03b1\u03bc\u03ad\u03bd\u03b7 \u03b5\u03ba\u03c0\u03bd\u03bf\u03ae \u03b5\u03bd\u03b5\u03c1\u03b3\u03bf\u03c0\u03bf\u03b9\u03b5\u03af \u03c4\u03bf \u03c0\u03b1\u03c1\u03b1\u03c3\u03c5\u03bc\u03c0\u03b1\u03b8\u03b7\u03c4\u03b9\u03ba\u03cc \u03bd\u03b5\u03c5\u03c1\u03b9\u03ba\u03cc \u03c3\u03cd\u03c3\u03c4\u03b7\u03bc\u03b1, \u03ba\u03b1\u03b8\u03b9\u03c3\u03c4\u03ce\u03bd\u03c4\u03b1\u03c2 \u03c4\u03b7\u03bd \u03b9\u03b4\u03b1\u03bd\u03b9\u03ba\u03ae \u03b3\u03b9\u03b1 \u03bd\u03b1 \u03b1\u03c0\u03bf\u03ba\u03bf\u03b9\u03bc\u03b7\u03b8\u03b5\u03af\u03c4\u03b5 \u03c3\u03b5 \u03bb\u03af\u03b3\u03b1 \u03bb\u03b5\u03c0\u03c4\u03ac.',
  'techniques.physioSigh.detail': '\u0391\u03bd\u03b1\u03ba\u03b1\u03bb\u03cd\u03c6\u03b8\u03b7\u03ba\u03b5 \u03b1\u03c0\u03cc \u03c4\u03bf\u03bd \u03bd\u03b5\u03c5\u03c1\u03bf\u03b5\u03c0\u03b9\u03c3\u03c4\u03ae\u03bc\u03bf\u03bd\u03b1 \u03c4\u03bf\u03c5 Stanford \u0394\u03c1. Andrew Huberman. \u039c\u03b9\u03b1 \u03b4\u03b9\u03c0\u03bb\u03ae \u03b5\u03b9\u03c3\u03c0\u03bd\u03bf\u03ae \u03b1\u03ba\u03bf\u03bb\u03bf\u03c5\u03b8\u03bf\u03cd\u03bc\u03b5\u03bd\u03b7 \u03b1\u03c0\u03cc \u03bc\u03b1\u03ba\u03c1\u03ac \u03b5\u03ba\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03bf \u03c0\u03b9\u03bf \u03b3\u03c1\u03ae\u03b3\u03bf\u03c1\u03bf\u03c2 \u03c4\u03c1\u03cc\u03c0\u03bf\u03c2 \u03bc\u03b5\u03af\u03c9\u03c3\u03b7\u03c2 \u03c4\u03bf\u03c5 \u03c3\u03c4\u03c1\u03b5\u03c2 \u03c3\u03b5 \u03c0\u03c1\u03b1\u03b3\u03bc\u03b1\u03c4\u03b9\u03ba\u03cc \u03c7\u03c1\u03cc\u03bd\u03bf.',
  'techniques.coherence.detail': '\u0397 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03bc\u03b5 5,5 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ad\u03c2 \u03c4\u03bf \u03bb\u03b5\u03c0\u03c4\u03cc \u03c3\u03c5\u03b3\u03c7\u03c1\u03bf\u03bd\u03af\u03b6\u03b5\u03b9 \u03ba\u03b1\u03c1\u03b4\u03b9\u03b1\u03ba\u03cc \u03c1\u03c5\u03b8\u03bc\u03cc, \u03b1\u03c1\u03c4\u03b7\u03c1\u03b9\u03b1\u03ba\u03ae \u03c0\u03af\u03b5\u03c3\u03b7 \u03ba\u03b1\u03b9 \u03bd\u03b5\u03c5\u03c1\u03b9\u03ba\u03cc \u03c3\u03cd\u03c3\u03c4\u03b7\u03bc\u03b1 \u2014 \u03b5\u03c0\u03b9\u03c4\u03c5\u03b3\u03c7\u03ac\u03bd\u03bf\u03bd\u03c4\u03b1\u03c2 \u03bc\u03b9\u03b1 \u03ba\u03b1\u03c4\u03ac\u03c3\u03c4\u03b1\u03c3\u03b7 \u03c0\u03bf\u03c5 \u03bf\u03bd\u03bf\u03bc\u03ac\u03b6\u03b5\u03c4\u03b1\u03b9 \u00ab\u03c3\u03c5\u03bd\u03bf\u03c7\u03ae\u00bb \u03b3\u03b9\u03b1 \u03b2\u03ad\u03bb\u03c4\u03b9\u03c3\u03c4\u03b7 HRV.',
  'techniques.triangle.detail': '\u0388\u03bd\u03b1 \u03b1\u03c0\u03b1\u03bb\u03cc \u03bc\u03bf\u03c4\u03af\u03b2\u03bf 3 \u03c6\u03ac\u03c3\u03b5\u03c9\u03bd \u03b9\u03b4\u03b1\u03bd\u03b9\u03ba\u03cc \u03b3\u03b9\u03b1 \u03b1\u03c1\u03c7\u03ac\u03c1\u03b9\u03bf\u03c5\u03c2. \u0395\u03be\u03b9\u03c3\u03bf\u03c1\u03c1\u03bf\u03c0\u03b5\u03af \u03c4\u03bf \u03bd\u03b5\u03c5\u03c1\u03b9\u03ba\u03cc \u03c3\u03cd\u03c3\u03c4\u03b7\u03bc\u03b1 \u03c7\u03c9\u03c1\u03af\u03c2 \u03c3\u03c5\u03b3\u03ba\u03c1\u03ac\u03c4\u03b7\u03c3\u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae\u03c2, \u03ba\u03ac\u03bd\u03bf\u03bd\u03c4\u03ac\u03c2 \u03c4\u03bf \u03b5\u03cd\u03ba\u03bf\u03bb\u03bf \u03ba\u03b1\u03b9 \u03c0\u03c1\u03bf\u03c3\u03b2\u03ac\u03c3\u03b9\u03bc\u03bf \u03b3\u03b9\u03b1 \u03cc\u03bb\u03bf\u03c5\u03c2.',
  'techniques.power.detail': '\u039c\u03b9\u03b1 \u03c0\u03c1\u03bf\u03b7\u03b3\u03bc\u03ad\u03bd\u03b7 \u03c4\u03b5\u03c7\u03bd\u03b9\u03ba\u03ae \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae\u03c2. \u0397 \u03b3\u03c1\u03ae\u03b3\u03bf\u03c1\u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b1\u03ba\u03bf\u03bb\u03bf\u03c5\u03b8\u03bf\u03cd\u03bc\u03b5\u03bd\u03b7 \u03b1\u03c0\u03cc \u03c3\u03c5\u03b3\u03ba\u03c1\u03ac\u03c4\u03b7\u03c3\u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae\u03c2 \u03b1\u03c5\u03be\u03ac\u03bd\u03b5\u03b9 \u03c4\u03b7\u03bd \u03b5\u03bd\u03ad\u03c1\u03b3\u03b5\u03b9\u03b1, \u03b1\u03bb\u03ba\u03b1\u03bb\u03bf\u03c0\u03bf\u03b9\u03b5\u03af \u03c4\u03bf \u03b1\u03af\u03bc\u03b1 \u03ba\u03b1\u03b9 \u03b5\u03bd\u03b9\u03c3\u03c7\u03cd\u03b5\u03b9 \u03c4\u03b7\u03bd \u03b1\u03bd\u03bf\u03c3\u03bf\u03bb\u03bf\u03b3\u03b9\u03ba\u03ae \u03b1\u03c0\u03cc\u03ba\u03c1\u03b9\u03c3\u03b7.',
  'techniques.fourFourSixTwo.detail': '\u0397 \u03c0\u03b1\u03c1\u03b1\u03c4\u03b5\u03c4\u03b1\u03bc\u03ad\u03bd\u03b7 \u03b5\u03ba\u03c0\u03bd\u03bf\u03ae (6\u03b4) \u03c3\u03b5 \u03c3\u03c7\u03ad\u03c3\u03b7 \u03bc\u03b5 \u03c4\u03b7\u03bd \u03b5\u03b9\u03c3\u03c0\u03bd\u03bf\u03ae (4\u03b4) \u03bf\u03b4\u03b7\u03b3\u03b5\u03af \u03c4\u03bf \u03c3\u03ce\u03bc\u03b1 \u03c3\u03b5 \u03b2\u03b1\u03b8\u03b9\u03ac \u03c7\u03b1\u03bb\u03ac\u03c1\u03c9\u03c3\u03b7. \u0397 \u03c3\u03cd\u03bd\u03c4\u03bf\u03bc\u03b7 \u03c0\u03b1\u03cd\u03c3\u03b7 \u03bc\u03b5\u03c4\u03b1\u03be\u03cd \u03c4\u03c9\u03bd \u03ba\u03cd\u03ba\u03bb\u03c9\u03bd \u03b5\u03c0\u03b1\u03bd\u03b1\u03c6\u03ad\u03c1\u03b5\u03b9 \u03c4\u03bf\u03bd \u03c1\u03c5\u03b8\u03bc\u03cc \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae\u03c2.',
  'techniques.kapalabhati.detail': '\u0391\u03c1\u03c7\u03b1\u03af\u03b1 \u03b3\u03b9\u03bf\u03b3\u03ba\u03b9\u03ba\u03ae \u03c4\u03b5\u03c7\u03bd\u03b9\u03ba\u03ae \u03c0\u03bf\u03c5 \u03c3\u03b7\u03bc\u03b1\u03af\u03bd\u03b5\u03b9 \u00ab\u03bb\u03b1\u03bc\u03c0\u03b5\u03c1\u03ae \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03ba\u03c1\u03b1\u03bd\u03af\u03bf\u03c5\u00bb. \u039f\u03b9 \u03b3\u03c1\u03ae\u03b3\u03bf\u03c1\u03b5\u03c2 \u03b4\u03c5\u03bd\u03b1\u03bc\u03b9\u03ba\u03ad\u03c2 \u03b5\u03ba\u03c0\u03bd\u03bf\u03ad\u03c2 \u03b5\u03bd\u03b5\u03c1\u03b3\u03bf\u03c0\u03bf\u03b9\u03bf\u03cd\u03bd \u03c4\u03bf \u03c3\u03ce\u03bc\u03b1, \u03ba\u03b1\u03b8\u03b1\u03c1\u03af\u03b6\u03bf\u03c5\u03bd \u03c4\u03bf \u03bc\u03c5\u03b1\u03bb\u03cc \u03ba\u03b1\u03b9 \u03b5\u03bd\u03b9\u03c3\u03c7\u03cd\u03bf\u03c5\u03bd \u03c4\u03bf \u03b4\u03b9\u03ac\u03c6\u03c1\u03b1\u03b3\u03bc\u03b1.',
  'techniques.twoToOne.detail': '\u0397 \u03b5\u03ba\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03b4\u03b9\u03c0\u03bb\u03ac\u03c3\u03b9\u03b1 \u03b1\u03c0\u03cc \u03c4\u03b7\u03bd \u03b5\u03b9\u03c3\u03c0\u03bd\u03bf\u03ae, \u03bc\u03b5\u03b3\u03b9\u03c3\u03c4\u03bf\u03c0\u03bf\u03b9\u03ce\u03bd\u03c4\u03b1\u03c2 \u03c4\u03b7\u03bd \u03b1\u03c0\u03b5\u03bb\u03b5\u03c5\u03b8\u03ad\u03c1\u03c9\u03c3\u03b7 CO\u2082 \u03ba\u03b1\u03b9 \u03b5\u03bd\u03b5\u03c1\u03b3\u03bf\u03c0\u03bf\u03b9\u03ce\u03bd\u03c4\u03b1\u03c2 \u03c4\u03bf \u03c0\u03bd\u03b5\u03c5\u03bc\u03bf\u03bd\u03bf\u03b3\u03b1\u03c3\u03c4\u03c1\u03b9\u03ba\u03cc \u03bd\u03b5\u03cd\u03c1\u03bf. \u0388\u03bd\u03b1 \u03b1\u03c0\u03cc \u03c4\u03b1 \u03c0\u03b9\u03bf \u03b1\u03c0\u03bf\u03c4\u03b5\u03bb\u03b5\u03c3\u03bc\u03b1\u03c4\u03b9\u03ba\u03ac \u03bc\u03bf\u03c4\u03af\u03b2\u03b1 \u03b3\u03b9\u03b1 \u03b2\u03b1\u03b8\u03b9\u03ac \u03c7\u03b1\u03bb\u03ac\u03c1\u03c9\u03c3\u03b7.',
  'techniques.cyclicSigh.detail': '\u0388\u03c1\u03b5\u03c5\u03bd\u03b1 \u03c4\u03bf\u03c5 Stanford \u03ad\u03b4\u03b5\u03b9\u03be\u03b5 \u03cc\u03c4\u03b9 5 \u03bb\u03b5\u03c0\u03c4\u03ac \u03ba\u03c5\u03ba\u03bb\u03b9\u03ba\u03bf\u03cd \u03b1\u03bd\u03b1\u03c3\u03c4\u03b5\u03bd\u03b1\u03b3\u03bc\u03bf\u03cd \u03b5\u03af\u03bd\u03b1\u03b9 \u03c0\u03b9\u03bf \u03b1\u03c0\u03bf\u03c4\u03b5\u03bb\u03b5\u03c3\u03bc\u03b1\u03c4\u03b9\u03ba\u03ac \u03c3\u03c4\u03b7 \u03bc\u03b5\u03af\u03c9\u03c3\u03b7 \u03c4\u03bf\u03c5 \u03c3\u03c4\u03c1\u03b5\u03c2 \u03b1\u03c0\u03cc \u03c4\u03bf\u03bd \u03b4\u03b9\u03b1\u03bb\u03bf\u03b3\u03b9\u03c3\u03bc\u03cc. \u0394\u03b9\u03c0\u03bb\u03ae \u03b5\u03b9\u03c3\u03c0\u03bd\u03bf\u03ae + \u03c0\u03b1\u03c1\u03b1\u03c4\u03b5\u03c4\u03b1\u03bc\u03ad\u03bd\u03b7 \u03b5\u03ba\u03c0\u03bd\u03bf\u03ae \u03b5\u03c0\u03b1\u03bd\u03b1\u03c6\u03ad\u03c1\u03b5\u03b9 \u03c4\u03bf \u03bd\u03b5\u03c5\u03c1\u03b9\u03ba\u03cc \u03c3\u03cd\u03c3\u03c4\u03b7\u03bc\u03b1.',

