  // Motivational quotes
  'summary.quote1': '\u00ab\u0397 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03b7 \u03b3\u03ad\u03c6\u03c5\u03c1\u03b1 \u03c0\u03bf\u03c5 \u03c3\u03c5\u03bd\u03b4\u03ad\u03b5\u03b9 \u03c4\u03b7 \u03b6\u03c9\u03ae \u03bc\u03b5 \u03c4\u03b7 \u03c3\u03c5\u03bd\u03b5\u03af\u03b4\u03b7\u03c3\u03b7.\u00bb \u2014 Thich Nhat Hanh',
  'summary.quote2': '\u00ab\u03a4\u03b1 \u03c3\u03c5\u03bd\u03b1\u03b9\u03c3\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1 \u03ad\u03c1\u03c7\u03bf\u03bd\u03c4\u03b1\u03b9 \u03ba\u03b1\u03b9 \u03c6\u03b5\u03cd\u03b3\u03bf\u03c5\u03bd \u03c3\u03b1\u03bd \u03c3\u03cd\u03bd\u03bd\u03b5\u03c6\u03b1 \u03c3\u03b5 \u03b1\u03bd\u03b5\u03bc\u03ce\u03b4\u03b7 \u03bf\u03c5\u03c1\u03b1\u03bd\u03cc. \u0397 \u03c3\u03c5\u03bd\u03b5\u03b9\u03b4\u03b7\u03c4\u03ae \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03b7 \u03ac\u03b3\u03ba\u03c5\u03c1\u03ac \u03bc\u03bf\u03c5.\u00bb \u2014 Thich Nhat Hanh',
  'summary.quote3': '\u00ab\u039f \u03bd\u03bf\u03c5\u03c2 \u03b5\u03af\u03bd\u03b1\u03b9 \u03bf \u03b2\u03b1\u03c3\u03b9\u03bb\u03b9\u03ac\u03c2 \u03c4\u03c9\u03bd \u03b1\u03b9\u03c3\u03b8\u03ae\u03c3\u03b5\u03c9\u03bd, \u03b1\u03bb\u03bb\u03ac \u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03bf \u03b2\u03b1\u03c3\u03b9\u03bb\u03b9\u03ac\u03c2 \u03c4\u03bf\u03c5 \u03bd\u03bf\u03c5.\u00bb \u2014 Hatha Yoga Pradipika',
  'summary.quote4': '\u00ab\u038c\u03c4\u03b1\u03bd \u03ba\u03b1\u03c4\u03ad\u03c7\u03b5\u03b9\u03c2 \u03c4\u03b7\u03bd \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03c3\u03bf\u03c5, \u03ba\u03b1\u03bd\u03b5\u03af\u03c2 \u03b4\u03b5\u03bd \u03bc\u03c0\u03bf\u03c1\u03b5\u03af \u03bd\u03b1 \u03ba\u03bb\u03ad\u03c8\u03b5\u03b9 \u03c4\u03b7\u03bd \u03b5\u03b9\u03c1\u03ae\u03bd\u03b7 \u03c3\u03bf\u03c5.\u00bb',
  'summary.quote5': '\u00ab\u0395\u03b9\u03c3\u03c0\u03bd\u03b5\u03cd\u03c3\u03c4\u03b5 \u03b7\u03c1\u03b5\u03bc\u03af\u03b1, \u03b5\u03ba\u03c0\u03bd\u03b5\u03cd\u03c3\u03c4\u03b5 \u03ad\u03bd\u03c4\u03b1\u03c3\u03b7.\u00bb',
  'summary.quote6': '\u00ab\u0397 \u03c0\u03b1\u03c1\u03bf\u03cd\u03c3\u03b1 \u03c3\u03c4\u03b9\u03b3\u03bc\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03b3\u03b5\u03bc\u03ac\u03c4\u03b7 \u03c7\u03b1\u03c1\u03ac \u03ba\u03b1\u03b9 \u03b5\u03c5\u03c4\u03c5\u03c7\u03af\u03b1. \u0391\u03bd \u03b5\u03af\u03c3\u03c4\u03b5 \u03c0\u03c1\u03bf\u03c3\u03b5\u03ba\u03c4\u03b9\u03ba\u03bf\u03af, \u03b8\u03b1 \u03c4\u03bf \u03b4\u03b5\u03af\u03c4\u03b5.\u00bb \u2014 Thich Nhat Hanh',
