  'summary.quote8': '\u00ab\u0391\u03c0\u03bb\u03ac \u03b1\u03bd\u03b1\u03c0\u03bd\u03b5\u03cd\u03c3\u03c4\u03b5. \u0395\u03af\u03c3\u03c4\u03b5 \u03b1\u03c1\u03ba\u03b5\u03c4\u03bf\u03af.\u00bb',
