  'summary.quote12': '\u00ab\u03a7\u03b1\u03bc\u03bf\u03b3\u03b5\u03bb\u03ae\u03c3\u03c4\u03b5, \u03b1\u03bd\u03b1\u03c0\u03bd\u03b5\u03cd\u03c3\u03c4\u03b5 \u03ba\u03b1\u03b9 \u03c0\u03c1\u03bf\u03c7\u03c9\u03c1\u03ae\u03c3\u03c4\u03b5 \u03b1\u03c1\u03b3\u03ac.\u00bb \u2014 Thich Nhat Hanh',
