  'summary.quote14': '\u00ab\u0393\u03b9\u03b1\u03c4\u03af \u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03b6\u03c9\u03ae, \u03ba\u03b1\u03b9 \u03b1\u03bd \u03b1\u03bd\u03b1\u03c0\u03bd\u03ad\u03b5\u03c4\u03b5 \u03ba\u03b1\u03bb\u03ac \u03b8\u03b1 \u03b6\u03ae\u03c3\u03b5\u03c4\u03b5 \u03c0\u03bf\u03bb\u03cd \u03c3\u03c4\u03b7 \u03b3\u03b7.\u00bb \u2014 \u03a3\u03b1\u03bd\u03c3\u03ba\u03c1\u03b9\u03c4\u03b9\u03ba\u03ae \u03c0\u03b1\u03c1\u03bf\u03b9\u03bc\u03af\u03b1',
