  'summary.quote17': '\u00ab\u039a\u03b1\u03c4\u03b1\u03ba\u03c4\u03ae\u03c3\u03c4\u03b5 \u03c4\u03b7\u03bd \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03c3\u03b1\u03c2, \u03b1\u03c6\u03ae\u03c3\u03c4\u03b5 \u03c4\u03bf\u03bd \u03b5\u03b1\u03c5\u03c4\u03cc \u03c3\u03b1\u03c2 \u03c3\u03c4\u03b7\u03bd \u03b5\u03c5\u03b4\u03b1\u03b9\u03bc\u03bf\u03bd\u03af\u03b1.\u00bb \u2014 T. Krishnamacharya',
