  'summary.quote19': '\u00ab\u038c\u03c4\u03b1\u03bd \u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03c0\u03b5\u03c1\u03b9\u03c0\u03bb\u03b1\u03bd\u03b9\u03ad\u03c4\u03b1\u03b9, \u03bf \u03bd\u03bf\u03c5\u03c2 \u03b5\u03af\u03bd\u03b1\u03b9 \u03b5\u03c0\u03af\u03c3\u03b7\u03c2 \u03b1\u03c3\u03c4\u03b1\u03b8\u03ae\u03c2. \u0391\u03bb\u03bb\u03ac \u03cc\u03c4\u03b1\u03bd \u03b7 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b7\u03c1\u03b5\u03bc\u03b5\u03af, \u03bf \u03bd\u03bf\u03c5\u03c2 \u03b8\u03b1 \u03b5\u03af\u03bd\u03b1\u03b9 \u03b5\u03c0\u03af\u03c3\u03b7\u03c2 \u03ae\u03c1\u03b5\u03bc\u03bf\u03c2.\u00bb \u2014 Hatha Yoga Pradipika',
