  'summary.quote21': '\u00ab\u0397 \u03b1\u03bd\u03b1\u03c0\u03bd\u03bf\u03ae \u03b5\u03af\u03bd\u03b1\u03b9 \u03c4\u03bf \u03c0\u03b9\u03bf \u03b5\u03ba\u03bb\u03b5\u03ba\u03c4\u03cc \u03b4\u03ce\u03c1\u03bf \u03c4\u03b7\u03c2 \u03c6\u03cd\u03c3\u03b7\u03c2. \u039d\u03b1 \u03b5\u03af\u03c3\u03c4\u03b5 \u03b5\u03c5\u03b3\u03bd\u03ce\u03bc\u03bf\u03bd\u03b5\u03c2 \u03b3\u03b9\u03b1 \u03b1\u03c5\u03c4\u03cc \u03c4\u03bf \u03c5\u03c0\u03ad\u03c1\u03bf\u03c7\u03bf \u03b4\u03ce\u03c1\u03bf.\u00bb \u2014 Amit Ray',
