  'summary.quote23': '\u00ab\u0388\u03bd\u03b1\u03c2 \u03ae\u03c1\u03b5\u03bc\u03bf\u03c2 \u03bd\u03bf\u03c5\u03c2 \u03c6\u03ad\u03c1\u03bd\u03b5\u03b9 \u03b5\u03c3\u03c9\u03c4\u03b5\u03c1\u03b9\u03ba\u03ae \u03b4\u03cd\u03bd\u03b1\u03bc\u03b7 \u03ba\u03b1\u03b9 \u03b1\u03c5\u03c4\u03bf\u03c0\u03b5\u03c0\u03bf\u03af\u03b8\u03b7\u03c3\u03b7.\u00bb \u2014 \u0394\u03b1\u03bb\u03ac\u03b9 \u039b\u03ac\u03bc\u03b1',
